import SwiftUI
import SwiftData
import ActivityKit
import CoreMotion
import CoreHaptics

struct ContentView: View {
    // Get ViewModels from ViewModelContainer
    @EnvironmentObject private var viewModelContainer: ViewModelContainer

    // Core ViewModels (essential for functionality)
    @StateObject private var timerViewModel = FocusTimerViewModel.shared
    @StateObject private var constellationViewModel = ConstellationViewModel()
    @StateObject private var dopamineDebtViewModel = DopamineDebtViewModel()

    // UI Effects (can be lazy loaded)
    @StateObject private var particleSystem = ParticleSystemViewModel()
    @StateObject private var breathingEngine = BreathingAnimationEngine()
    @StateObject private var hapticEngine = HapticEngine()
    @State private var showingAppPicker = false
    @State private var showingProfile = false
    @State private var selectedCard: CardType? = nil
    @State private var dragOffset = CGSize.zero
    @State private var currentTime = Date()
    @State private var timerScale: CGFloat = 1.0
    @State private var isFullscreenFocus = false
    @State private var lastSwipeTime = Date()
    @State private var deviceTilt: Double = 0
    @State private var liquidMorphPhase: CGFloat = 0

    // Gesture states
    @State private var isPinching = false
    @State private var currentPinchScale: CGFloat = 1.0
    @State private var timerDragOffset: CGSize = .zero

    // Motion manager for parallax
    private let motionManager = CMMotionManager()

    let timer = Timer.publish(every: 1, on: .main, in: .common).autoconnect()

    var greeting: String {
        let hour = Calendar.current.component(.hour, from: currentTime)
        switch hour {
        case 5..<12: return "Good Morning"
        case 12..<17: return "Good Afternoon"
        case 17..<22: return "Good Evening"
        default: return "Good Night"
        }
    }

    var body: some View {
        ZStack {
            // Animated gradient background with breathing
            AnimatedBackgroundView(breathingScale: breathingEngine.scale)
                .overlay(
                    // Particle System Layer
                    ParticleFieldView(
                        particles: particleSystem.particles,
                        isActive: timerViewModel.isRunning && !timerViewModel.isPaused
                    )
                )

            if !isFullscreenFocus {
                ScrollView(showsIndicators: false) {
                    VStack(spacing: 20) {
                        // Header with greeting
                        HeaderView(
                            greeting: greeting,
                            currentTime: currentTime,
                            pickupTracker: viewModelContainer.pickupTracker

{"output":"                    }
                }
            }
            .onEnded { _ in
                withAnimation(.spring()) {
                    currentPinchScale = 1.0
                }
            }
    }

    private func createSwipeGesture() -> some Gesture {
        DragGesture(minimumDistance: 50)
            .onEnded { value in
                // Only start timer on deliberate swipe up, not during selection
                if value.translation.height < -100 && 
                   timerViewModel.selectedPreset != nil && 
                   !timerViewModel.isRunning {
                    // Swipe up to quick start
                    timerViewModel.startTimer()
                    hapticEngine.playQuickStart()
                    liquidMorphPhase = 1.0
                    withAnimation(.easeOut(duration: 0.8)) {
                        liquidMorphPhase = 0
                    }
                }
            }
    }

    // MARK: - Setup Functions
    private func setupMotionManager() {
        guard motionManager.isDeviceMotionAvailable else { return }
        motionManager.deviceMotionUpdateInterval = 0.1
        motionManager.startDeviceMotionUpdates(to: .main) { motion, error in
            guard let motion = motion else { return }
            withAnimation(.easeOut(duration: 0.3)) {
                deviceTilt = motion.attitude.pitch * 180 / .pi
            }
        }
    }

    private func startLiveActivity() {
        guard timerViewModel.isRunning else { return }

        // Live Activity is implemented in FocusActivityAttributes.swift
        // The actual Live Activity requires an App Extension target
        // For now, using dynamic island and notification updates
        #if DEBUG
        print("Live Activity would start here")
        #endif
    }
}

