    private func sendBlockingNotification(for zone: BlockedZone, isEntering: Bool) {
        let content = UNMutableNotificationContent()
        content.title = isEntering ? "Entering Focus Zone" : "Leaving Focus Zone"
        content.body = isEntering 
            ? "Apps are now blocked in \(zone.name)"
            : "Apps are now unblocked"
        content.sound = .default

        let request = UNNotificationRequest(
            identifier: UUID().uuidString,
            content: content,
            trigger: nil
        )

        UNUserNotificationCenter.current().add(request)
    }

    // MARK: - Persistence

    private func saveBlockedZones() {
        if let data = try? JSONEncoder().encode(blockedZones) {
            UserDefaults.standard.set(data, forKey: "location_blocked_zones")
        }
    }

    private func loadBlockedZones() {
        if let data = UserDefaults.standard.data(forKey: "location_blocked_zones"),
           let zones = try? JSONDecoder().decode([BlockedZone].self, from: data) {
            blockedZones = zones
        } else {
            // Add default zones
            createDefaultZones()
        }
    }

    private func createDefaultZones() {
        // Example: Work location
        let workZone = BlockedZone(
