        }

        // Only use actual tracked data, no defaults
        if weeklyTotal > 0 {
            weeklyScreenTime = weeklyTotal

            // Get actual app usage from analytics
            if !analyticsManager.topDistractingApps.isEmpty {
                appUsage = analyticsManager.topDistractingApps.prefix(3).map { app in
                    (app: app.name, minutes: Double(app.minutes))
                }
                if let topApp = analyticsManager.topDistractingApps.first {
                    self.topApp = topApp.name
                }
            } else {
                // If no app-specific data, distribute screen time across common apps
                let avgMinutes = weeklyTotal / 3
                appUsage = [
                    (app: "Social Media", minutes: avgMinutes),
                    (app: "Entertainment", minutes: avgMinutes),
                    (app: "Other Apps", minutes: avgMinutes)
                ]
                topApp = "your apps"
            }
        } else {
            // No screen time tracked - show zero usage
            weeklyScreenTime = 0
            appUsage = []
            topApp = "No apps"
        }

        // Calculate notifications based on actual pickups
        let estimatedPickups = analyticsManager.todayPickups
        dailyNotifications = max(estimatedPickups * 8, 0)
    }

    func calculateMoneyLost(hourlyRate: Double) -> Double {
        let totalMinutesToday = appUsage.reduce(0) { $0 + $1.minutes }
        return (totalMinutesToday / 60) * hourlyRate
    }

    func topAppsWithCost(hourlyRate: Double) -> [(name: String, cost: Double)] {
        if appUsage.isEmpty {
            return [
                (name: "No apps tracked", cost: 0.0)
            ]
        }

        return appUsage.map { app in
            (name: app.app, cost: (app.minutes / 60) * hourlyRate)
        }
    }
}

