    func completeSession(duration: Int, wasPlanned: Bool) -> Int {
        guard !currentSessionQuality.isLowQuality else { return 0 }

        var bonusFP = 0

        // Completion bonus only for planned sessions
        if wasPlanned && duration >= 5 { // Min 5 minutes for bonus
            bonusFP = config.fpEarning.completionBonus

            // Apply boost if active
            if boostActive {
                bonusFP *= 2
