    // ViewModels
    @Published var focusTimer: FocusTimerViewModel
    @Published var constellation: ConstellationViewModelSwiftData
    @Published var dopamineDebt: DopamineDebtViewModelSwiftData
    @Published var analytics: AnalyticsDataManagerSwiftData
    @Published var pickupTracker: PickupTrackerViewModel

    init(modelContext: ModelContext) {
        self.modelContext = modelContext
        self.contextActor = ModelContextActor(modelContext: modelContext)

        // Initialize ViewModels
        self.focusTimer = FocusTimerViewModel.shared
        self.constellation = ConstellationViewModelSwiftData()
        self.dopamineDebt = DopamineDebtViewModelSwiftData()
        self.analytics = AnalyticsDataManagerSwiftData()
        self.pickupTracker = PickupTrackerViewModel()

        // Set model context for each ViewModel
        focusTimer.setModelContext(modelContext)
        constellation.setModelContext(modelContext)
        dopamineDebt.setModelContext(modelContext)
        analytics.setModelContext(modelContext)
        // pickupTracker doesn't use SwiftData directly yet

        // Setup inter-ViewModel connections
        setupConnections()
    }

    // Thread-safe save method for all ViewModels to use
    func saveContext() {
        do {
            try contextActor.performOperation { context in
                try context.save()
            }
        } catch {
            print("Error saving context: \(error)")
        }
    }

    private func setupConnections() {
        let observerKey = "ViewModelContainer.focusObservers"
        focusTimer.unregisterFocusObservers(for: observerKey)

        // Connect FocusTimer to Constellation
        focusTimer.registerFocusStartObserver(observerKey) { [weak self] duration in
            self?.constellation.startNewSession(focusDuration: duration)
        }

        focusTimer.registerFocusProgressObserver(observerKey) { [weak self] elapsedMinutes in
            self?.constellation.updateSessionProgress(elapsedMinutes: elapsedMinutes)
        }

        focusTimer.registerFocusAbandonObserver(observerKey) { [weak self] in
            self?.constellation.abandonSession()
        }

        // Connect FocusTimer to DopamineDebt
        focusTimer.registerFocusCompleteObserver(observerKey) { [weak self] minutes in
            self?.dopamineDebt.reduceDopamineDebt(by: minutes * 2)
        }
    }
}

